export function sumReportedUsage(rounds: Array<UsageMetadata | undefined>): UsageMetadata | undefined {
  const reported = rounds.filter(round => round !== undefined);
  if (reported.length === 0) return undefined;

  return reported.reduce((total, round) => ({
    inputTokens: total.inputTokens + round.inputTokens,
    outputTokens: total.outputTokens + round.outputTokens,
    totalTokens: total.totalTokens + round.totalTokens,
  }));
}

